class Solution { fun constrainedSubsetSum(nums:IntArray,k:Int):Int{val dp=IntArray(nums.size);val deque=java.util.ArrayDeque<Int>();var answer=Int.MIN_VALUE;for(i in nums.indices){while(deque.isNotEmpty()&&deque.peekFirst()<i-k)deque.removeFirst();dp[i]=nums[i]+if(deque.isEmpty())0 else maxOf(0,dp[deque.peekFirst()]);while(deque.isNotEmpty()&&dp[deque.peekLast()]<=dp[i])deque.removeLast();deque.addLast(i);answer=maxOf(answer,dp[i])};return answer} }
